mapper.update:
UPDATE spectra_core.scheduler_execution
SET status = 'QUEUED',
    next_retry_at = NULL,
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'RETRY_WAIT'
  AND next_retry_at IS NOT NULL
  AND next_retry_at <= #{now}

UPDATE spectra_core.scheduler_execution
SET last_heartbeat_at = #{heartbeatAt},
    lease_expires_at = #{leaseExpiresAt},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'RUNNING'
  AND locked_by = #{instanceId}
  AND lease_expires_at >= #{heartbeatAt}

UPDATE spectra_core.scheduler_execution
SET status = #{status},
    finished_at = #{finishedAt},
    locked_by = NULL,
    locked_at = NULL,
    lease_expires_at = NULL,
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'RUNNING'
  AND locked_by = #{instanceId}
  AND lease_expires_at >= #{finishedAt}
